diff --git a/applets/systemtray/autotests/mocktraymodel.h b/applets/systemtray/autotests/mocktraymodel.h
new file mode 100644
index 0000000000..07c951e413
--- /dev/null
+++ b/applets/systemtray/autotests/mocktraymodel.h
@@ -0,0 +1,88 @@
+/*
+    SPDX-FileCopyrightText: 2026 Ramil Nurmanov <ramil2004nur@gmail.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#pragma once
+
+#include <QAbstractListModel>
+
+#include "../systemtraymodel.h"
+
+class MockTrayModel : public QAbstractListModel
+{
+public:
+    struct Item {
+        QString itemId;
+        QString category;
+        QString name;
+    };
+
+    explicit MockTrayModel(const QList<Item> &items = {})
+        : m_items(items)
+    {
+    }
+
+    void append(const Item &item)
+    {
+        beginInsertRows(QModelIndex(), m_items.size(), m_items.size());
+        m_items.append(item);
+        endInsertRows();
+    }
+
+    void remove(int row)
+    {
+        beginRemoveRows(QModelIndex(), row, row);
+        m_items.removeAt(row);
+        endRemoveRows();
+    }
+
+    void move(int from, int to)
+    {
+        beginMoveRows(QModelIndex(), from, from, QModelIndex(), to > from ? to + 1 : to);
+        m_items.move(from, to);
+        endMoveRows();
+    }
+
+    void setName(int row, const QString &name, const QList<int> &roles = {Qt::DisplayRole})
+    {
+        m_items[row].name = name;
+        Q_EMIT dataChanged(index(row, 0), index(row, 0), roles);
+    }
+
+    int rowCount(const QModelIndex &parent = QModelIndex()) const override
+    {
+        return parent.isValid() ? 0 : m_items.size();
+    }
+
+    QVariant data(const QModelIndex &index, int role) const override
+    {
+        if (!checkIndex(index, CheckIndexOption::IndexIsValid)) {
+            return {};
+        }
+        const Item &item = m_items.at(index.row());
+        switch (role) {
+        case Qt::DisplayRole:
+            return item.name.isEmpty() ? item.itemId : item.name;
+        case static_cast<int>(BaseModel::BaseRole::ItemId):
+            return item.itemId;
+        case static_cast<int>(BaseModel::BaseRole::Category):
+            return item.category;
+        default:
+            return {};
+        }
+    }
+
+    QHash<int, QByteArray> roleNames() const override
+    {
+        return {
+            {Qt::DisplayRole, QByteArrayLiteral("displayText")},
+            {static_cast<int>(BaseModel::BaseRole::ItemId), QByteArrayLiteral("itemId")},
+            {static_cast<int>(BaseModel::BaseRole::Category), QByteArrayLiteral("category")},
+        };
+    }
+
+private:
+    QList<Item> m_items;
+};
diff --git a/applets/systemtray/autotests/sortedsystemtraymodeltest.cpp b/applets/systemtray/autotests/sortedsystemtraymodeltest.cpp
new file mode 100644
index 0000000000..76dbd32ff8
--- /dev/null
+++ b/applets/systemtray/autotests/sortedsystemtraymodeltest.cpp
@@ -0,0 +1,216 @@
+/*
+    SPDX-FileCopyrightText: 2026 Ramil Nurmanov <ramil2004nur@gmail.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include <QFile>
+#include <QTemporaryDir>
+#include <QTest>
+
+#include <KConfigLoader>
+
+#include "../sortedsystemtraymodel.h"
+#include "../systemtraymodel.h"
+#include "../systemtraysettings.h"
+#include "mocktraymodel.h"
+
+using namespace Qt::StringLiterals;
+
+class SortedSystemTrayModelTest : public QObject
+{
+    Q_OBJECT
+private:
+    bool saveManualOrder(const QStringList &order);
+    static QStringList itemIds(const QAbstractItemModel &model);
+
+    QTemporaryDir *m_tempDir = nullptr;
+    KConfigLoader *m_config = nullptr;
+
+private Q_SLOTS:
+    void init();
+    void cleanup();
+
+    void testDefaultOrder();
+    void testDefaultOrderNotificationsFirst();
+    void testCustomOrderMovesNotifications();
+    void testCustomOrderNoDuplicates();
+    void testCustomOrderWithDuplicateItemIds();
+    void testUnlistedItemsFollowListedOnes();
+    void testCustomOrderIgnoredWhenGrouped();
+};
+
+void SortedSystemTrayModelTest::init()
+{
+    m_tempDir = new QTemporaryDir();
+    QVERIFY(m_tempDir->isValid());
+
+    QFile schemaFile(QFINDTESTDATA("../main.xml"));
+    m_config = new KConfigLoader(m_tempDir->filePath(u"systraysettingsrc"_s), &schemaFile);
+    QVERIFY(m_config->findItemByName(u"manualIconOrder"_s));
+    QVERIFY(m_config->findItemByName(u"iconOrder"_s));
+}
+
+void SortedSystemTrayModelTest::cleanup()
+{
+    delete m_config;
+    m_config = nullptr;
+    delete m_tempDir;
+    m_tempDir = nullptr;
+}
+
+bool SortedSystemTrayModelTest::saveManualOrder(const QStringList &order)
+{
+    m_config->findItemByName(u"manualIconOrder"_s)->setProperty(true);
+    m_config->findItemByName(u"iconOrder"_s)->setProperty(order);
+    return m_config->save();
+}
+
+QStringList SortedSystemTrayModelTest::itemIds(const QAbstractItemModel &model)
+{
+    QStringList ids;
+    for (int row = 0; row < model.rowCount(); ++row) {
+        ids.append(model.index(row, 0).data(static_cast<int>(BaseModel::BaseRole::ItemId)).toString());
+    }
+    return ids;
+}
+
+void SortedSystemTrayModelTest::testDefaultOrder()
+{
+    SystemTraySettings settings(m_config);
+
+    MockTrayModel source({
+        {u"hardware"_s, u"Hardware"_s},
+        {u"zulu"_s, u"ApplicationStatus"_s},
+        {u"alpha"_s, u"ApplicationStatus"_s},
+        {u"unknown"_s, u"SomethingElse"_s},
+    });
+
+    SortedSystemTrayModel proxy(&settings);
+    proxy.setSourceModel(&source);
+
+    QCOMPARE(itemIds(proxy), (QStringList{u"unknown"_s, u"alpha"_s, u"zulu"_s, u"hardware"_s}));
+}
+
+void SortedSystemTrayModelTest::testDefaultOrderNotificationsFirst()
+{
+    SystemTraySettings settings(m_config);
+
+    MockTrayModel source({
+        {u"alpha"_s, u"ApplicationStatus"_s},
+        {u"org.kde.plasma.notifications"_s, u"SystemServices"_s},
+        {u"unknown"_s, u"UnknownCategory"_s},
+    });
+
+    SortedSystemTrayModel proxy(&settings);
+    proxy.setSourceModel(&source);
+
+    QCOMPARE(itemIds(proxy), (QStringList{u"org.kde.plasma.notifications"_s, u"unknown"_s, u"alpha"_s}));
+}
+
+void SortedSystemTrayModelTest::testCustomOrderMovesNotifications()
+{
+    SystemTraySettings settings(m_config);
+
+    MockTrayModel source({
+        {u"alpha"_s, u"ApplicationStatus"_s},
+        {u"org.kde.plasma.notifications"_s, u"SystemServices"_s},
+        {u"unknown"_s, u"UnknownCategory"_s},
+    });
+
+    SortedSystemTrayModel proxy(&settings);
+    proxy.setSourceModel(&source);
+
+    QCOMPARE(itemIds(proxy), (QStringList{u"org.kde.plasma.notifications"_s, u"unknown"_s, u"alpha"_s}));
+    QVERIFY(saveManualOrder({u"alpha"_s, u"org.kde.plasma.notifications"_s}));
+
+    QCOMPARE(itemIds(proxy), (QStringList{u"alpha"_s, u"org.kde.plasma.notifications"_s, u"unknown"_s}));
+}
+
+void SortedSystemTrayModelTest::testCustomOrderNoDuplicates()
+{
+    SystemTraySettings settings(m_config);
+
+    MockTrayModel source({
+        {u"a"_s, u"ApplicationStatus"_s},
+        {u"b"_s, u"ApplicationStatus"_s},
+        {u"c"_s, u"ApplicationStatus"_s},
+    });
+
+    SortedSystemTrayModel proxy(&settings);
+    proxy.setSourceModel(&source);
+
+    QVERIFY(saveManualOrder({u"c"_s, u"a"_s, u"b"_s}));
+
+    QCOMPARE(itemIds(proxy), (QStringList{u"c"_s, u"a"_s, u"b"_s}));
+}
+
+void SortedSystemTrayModelTest::testCustomOrderWithDuplicateItemIds()
+{
+    SystemTraySettings settings(m_config);
+
+    MockTrayModel source({
+        {u"foo"_s, u"ApplicationStatus"_s},
+        {u"foo"_s, u"ApplicationStatus"_s},
+        {u"bar"_s, u"ApplicationStatus"_s},
+    });
+
+    SortedSystemTrayModel proxy(&settings);
+    proxy.setSourceModel(&source);
+
+    QVERIFY(saveManualOrder({u"foo"_s, u"bar"_s, u"foo"_s}));
+
+    QCOMPARE(itemIds(proxy), (QStringList{u"foo"_s, u"bar"_s, u"foo"_s}));
+    QCOMPARE(proxy.mapToSource(proxy.index(0, 0)).row(), 0);
+    QCOMPARE(proxy.mapToSource(proxy.index(2, 0)).row(), 1);
+}
+
+void SortedSystemTrayModelTest::testUnlistedItemsFollowListedOnes()
+{
+    SystemTraySettings settings(m_config);
+
+    MockTrayModel source({
+        {u"app"_s, u"ApplicationStatus"_s},
+        {u"hardware"_s, u"Hardware"_s},
+        {u"communications"_s, u"Communications"_s},
+        {u"unknown"_s, u"UnknownCategory"_s},
+    });
+
+    SortedSystemTrayModel proxy(&settings);
+    proxy.setSourceModel(&source);
+
+    QVERIFY(saveManualOrder({u"hardware"_s, u"app"_s}));
+
+    QCOMPARE(itemIds(proxy), (QStringList{u"hardware"_s, u"app"_s, u"unknown"_s, u"communications"_s}));
+}
+
+void SortedSystemTrayModelTest::testCustomOrderIgnoredWhenGrouped()
+{
+    SystemTraySettings settings(m_config);
+
+    MockTrayModel source({
+        {u"a"_s, u"ApplicationStatus"_s},
+        {u"b"_s, u"ApplicationStatus"_s},
+        {u"c"_s, u"ApplicationStatus"_s},
+    });
+
+    SortedSystemTrayModel proxy(&settings);
+    proxy.setSourceModel(&source);
+
+    m_config->findItemByName(u"iconOrder"_s)->setProperty(QStringList{u"c"_s, u"a"_s, u"b"_s});
+    QVERIFY(m_config->save());
+    QCOMPARE(itemIds(proxy), (QStringList{u"a"_s, u"b"_s, u"c"_s}));
+
+    m_config->findItemByName(u"manualIconOrder"_s)->setProperty(true);
+    QVERIFY(m_config->save());
+    QCOMPARE(itemIds(proxy), (QStringList{u"c"_s, u"a"_s, u"b"_s}));
+
+    m_config->findItemByName(u"manualIconOrder"_s)->setProperty(false);
+    QVERIFY(m_config->save());
+    QCOMPARE(itemIds(proxy), (QStringList{u"a"_s, u"b"_s, u"c"_s}));
+    QCOMPARE(settings.itemOrder(), (QStringList{u"c"_s, u"a"_s, u"b"_s}));
+}
+
+QTEST_MAIN(SortedSystemTrayModelTest)
+
+#include "sortedsystemtraymodeltest.moc"
diff --git a/applets/systemtray/autotests/systemtrayconfigmodeltest.cpp b/applets/systemtray/autotests/systemtrayconfigmodeltest.cpp
new file mode 100644
index 0000000000..48b902b4f3
--- /dev/null
+++ b/applets/systemtray/autotests/systemtrayconfigmodeltest.cpp
@@ -0,0 +1,397 @@
+/*
+    SPDX-FileCopyrightText: 2026 Ramil Nurmanov <ramil2004nur@gmail.com>
+
+    SPDX-License-Identifier: LGPL-2.1-only OR LGPL-3.0-only OR LicenseRef-KDE-Accepted-LGPL
+*/
+
+#include <QAbstractItemModelTester>
+#include <QSignalSpy>
+#include <QTest>
+
+#include "../systemtrayconfigmodel.h"
+#include "../systemtraymodel.h"
+#include "mocktraymodel.h"
+
+using namespace Qt::StringLiterals;
+
+class SystemTrayConfigModelTest : public QObject
+{
+    Q_OBJECT
+private:
+    static QStringList rows(const SystemTrayConfigModel &model);
+    static QStringList names(const QAbstractItemModel &model);
+    static QList<MockTrayModel::Item> items();
+
+private Q_SLOTS:
+    void testGroupedByCategory();
+    void testUnknownCategoriesShareSection();
+    void testManualOrder();
+    void testSwitchingOrderMode();
+    void testSwitchingOrderModeKeepsNotificationsFirst();
+    void testMove();
+    void testMoveKeepsPositionOfAbsentItems();
+    void testMoveIgnoredWhenGroupedOrFiltered();
+    void testFilter();
+    void testSourceChangesWhileGrouped();
+    void testSourceChangesWithManualOrder();
+    void testSourceDestroyed();
+    void testSourceRowsMoved();
+    void testDataChangedWithoutOrderRoles();
+    void testMoveWithDuplicateItemIds();
+};
+
+QStringList SystemTrayConfigModelTest::rows(const SystemTrayConfigModel &model)
+{
+    QStringList rows;
+    QString lastCategory;
+    for (int row = 0; row < model.rowCount(); ++row) {
+        const QModelIndex index = model.index(row, 0);
+        const QString category = index.data(static_cast<int>(BaseModel::BaseRole::Category)).toString();
+        if (model.isGrouped() && category != lastCategory) {
+            rows.append(u'#' + category);
+            lastCategory = category;
+        }
+        rows.append(index.data(static_cast<int>(BaseModel::BaseRole::ItemId)).toString());
+    }
+    return rows;
+}
+
+QStringList SystemTrayConfigModelTest::names(const QAbstractItemModel &model)
+{
+    QStringList names;
+    for (int row = 0; row < model.rowCount(); ++row) {
+        names.append(model.index(row, 0).data(Qt::DisplayRole).toString());
+    }
+    return names;
+}
+
+QList<MockTrayModel::Item> SystemTrayConfigModelTest::items()
+{
+    return {
+        {u"hotel"_s, u"Hardware"_s},
+        {u"bravo"_s, u"ApplicationStatus"_s},
+        {u"alpha"_s, u"ApplicationStatus"_s},
+    };
+}
+
+void SystemTrayConfigModelTest::testGroupedByCategory()
+{
+    MockTrayModel source(items());
+    SystemTrayConfigModel model;
+    model.setSourceModel(&source);
+    QAbstractItemModelTester tester(&model, QAbstractItemModelTester::FailureReportingMode::QtTest);
+
+    QVERIFY(model.isGrouped());
+    QCOMPARE(rows(model), (QStringList{u"#ApplicationStatus"_s, u"alpha"_s, u"bravo"_s, u"#Hardware"_s, u"hotel"_s}));
+    QCOMPARE(model.rowCount(), 3);
+}
+
+void SystemTrayConfigModelTest::testUnknownCategoriesShareSection()
+{
+    MockTrayModel source({
+        {u"alpha"_s, u"Foo"_s},
+        {u"bravo"_s, QString()},
+        {u"charlie"_s, u"UnknownCategory"_s},
+    });
+    SystemTrayConfigModel model;
+    model.setSourceModel(&source);
+    QAbstractItemModelTester tester(&model, QAbstractItemModelTester::FailureReportingMode::QtTest);
+
+    QCOMPARE(rows(model), (QStringList{u"#UnknownCategory"_s, u"alpha"_s, u"bravo"_s, u"charlie"_s}));
+}
+
+void SystemTrayConfigModelTest::testManualOrder()
+{
+    MockTrayModel source(items());
+    SystemTrayConfigModel model;
+    model.setSourceModel(&source);
+    QAbstractItemModelTester tester(&model, QAbstractItemModelTester::FailureReportingMode::QtTest);
+    QSignalSpy resetSpy(&model, &QAbstractItemModel::modelReset);
+
+    model.setOrder({u"hotel"_s, u"alpha"_s, u"bravo"_s});
+    model.setGrouped(false);
+
+    QVERIFY(!model.isGrouped());
+    QCOMPARE(rows(model), (QStringList{u"hotel"_s, u"alpha"_s, u"bravo"_s}));
+    QCOMPARE(resetSpy.count(), 0);
+}
+
+void SystemTrayConfigModelTest::testSwitchingOrderMode()
+{
+    MockTrayModel source(items());
+    SystemTrayConfigModel model;
+    model.setSourceModel(&source);
+    QAbstractItemModelTester tester(&model, QAbstractItemModelTester::FailureReportingMode::QtTest);
+    QSignalSpy orderSpy(&model, &SystemTrayConfigModel::orderChanged);
+    QSignalSpy groupedSpy(&model, &SystemTrayConfigModel::groupedChanged);
+    QSignalSpy layoutSpy(&model, &QAbstractItemModel::layoutChanged);
+    QSignalSpy resetSpy(&model, &QAbstractItemModel::modelReset);
+
+    model.setGrouped(false);
+    QCOMPARE(groupedSpy.count(), 1);
+    QCOMPARE(orderSpy.count(), 0);
+    QVERIFY(model.order().isEmpty());
+    QCOMPARE(rows(model), (QStringList{u"alpha"_s, u"bravo"_s, u"hotel"_s}));
+
+    model.setGrouped(false);
+    QCOMPARE(groupedSpy.count(), 1);
+
+    model.move(0, 2);
+    QCOMPARE(rows(model), (QStringList{u"bravo"_s, u"hotel"_s, u"alpha"_s}));
+    QCOMPARE(model.order(), (QStringList{u"bravo"_s, u"hotel"_s, u"alpha"_s}));
+    QCOMPARE(orderSpy.count(), 1);
+    QSignalSpy moveSpy(&model, &QAbstractItemModel::rowsMoved);
+
+    model.setGrouped(true);
+    QCOMPARE(groupedSpy.count(), 2);
+    QCOMPARE(rows(model), (QStringList{u"#ApplicationStatus"_s, u"alpha"_s, u"bravo"_s, u"#Hardware"_s, u"hotel"_s}));
+    QVERIFY(moveSpy.count() > 0);
+
+    model.setGrouped(false);
+    QCOMPARE(groupedSpy.count(), 3);
+    QCOMPARE(orderSpy.count(), 1);
+    QCOMPARE(model.order(), (QStringList{u"bravo"_s, u"hotel"_s, u"alpha"_s}));
+    QCOMPARE(rows(model), (QStringList{u"bravo"_s, u"hotel"_s, u"alpha"_s}));
+    QCOMPARE(layoutSpy.count(), 0);
+    QCOMPARE(resetSpy.count(), 0);
+}
+
+void SystemTrayConfigModelTest::testSwitchingOrderModeKeepsNotificationsFirst()
+{
+    QList<MockTrayModel::Item> trayItems = items();
+    trayItems.append({u"org.kde.plasma.notifications"_s, u"SystemServices"_s});
+    MockTrayModel source(trayItems);
+    SystemTrayConfigModel model;
+    model.setSourceModel(&source);
+    QAbstractItemModelTester tester(&model, QAbstractItemModelTester::FailureReportingMode::QtTest);
+
+    QCOMPARE(
+        rows(model),
+        (QStringList{u"#ApplicationStatus"_s, u"alpha"_s, u"bravo"_s, u"#SystemServices"_s, u"org.kde.plasma.notifications"_s, u"#Hardware"_s, u"hotel"_s}));
+
+    model.setGrouped(false);
+    QCOMPARE(rows(model), (QStringList{u"org.kde.plasma.notifications"_s, u"alpha"_s, u"bravo"_s, u"hotel"_s}));
+
+    model.move(3, 2);
+    QCOMPARE(model.order(), (QStringList{u"org.kde.plasma.notifications"_s, u"alpha"_s, u"hotel"_s, u"bravo"_s}));
+}
+
+void SystemTrayConfigModelTest::testMove()
+{
+    MockTrayModel source(items());
+    SystemTrayConfigModel model;
+    model.setSourceModel(&source);
+    QAbstractItemModelTester tester(&model, QAbstractItemModelTester::FailureReportingMode::QtTest);
+    model.setOrder({u"alpha"_s, u"bravo"_s, u"hotel"_s});
+    model.setGrouped(false);
+
+    QSignalSpy moveSpy(&model, &QAbstractItemModel::rowsMoved);
+    QSignalSpy layoutSpy(&model, &QAbstractItemModel::layoutChanged);
+    QSignalSpy orderSpy(&model, &SystemTrayConfigModel::orderChanged);
+
+    model.move(0, 2);
+    QCOMPARE(rows(model), (QStringList{u"bravo"_s, u"hotel"_s, u"alpha"_s}));
+    QCOMPARE(model.order(), (QStringList{u"bravo"_s, u"hotel"_s, u"alpha"_s}));
+
+    model.move(2, 1);
+    QCOMPARE(rows(model), (QStringList{u"bravo"_s, u"alpha"_s, u"hotel"_s}));
+    QCOMPARE(model.order(), (QStringList{u"bravo"_s, u"alpha"_s, u"hotel"_s}));
+
+    QCOMPARE(moveSpy.count(), 2);
+    QCOMPARE(layoutSpy.count(), 0);
+    QCOMPARE(orderSpy.count(), 2);
+}
+
+void SystemTrayConfigModelTest::testMoveKeepsPositionOfAbsentItems()
+{
+    MockTrayModel source(items());
